from ansible_builder.requirements import sanitize_requirements


def test_combine_entries():
    assert sanitize_requirements({
        'foo.bar': ['foo>1.0'],
        'bar.foo': ['foo>=2.0']
    }) == ['foo>1.0,>=2.0  # from collection foo.bar,bar.foo']


def test_remove_unwanted_requirements():
    assert sanitize_requirements({
        'foo.bar': [
            'foo',
            'ansible',
            'bar',
        ],
        'bar.foo': [
            'pytest',
            'bar',
            'zoo'
        ]
    }) == [
        'foo  # from collection foo.bar',
        'bar  # from collection foo.bar,bar.foo',
        'zoo  # from collection bar.foo'
    ]


def test_skip_bad_formats():
    """A single incorrectly formatted requirement should warn, but not block other reqs"""
    assert sanitize_requirements({'foo.bar': [
        'foo',
        'bar'
    ], 'foo.bad': ['zizzer zazzer zuzz']  # not okay
    }) == ['foo  # from collection foo.bar', 'bar  # from collection foo.bar']


def test_user_specified_excluded_requirements_preserved():
    """Test that user-specified requirements in EXCLUDE_REQUIREMENTS are preserved."""
    # Test that user-specified yamllint and ansible-lint are preserved
    result = sanitize_requirements({
        'user': ['yamllint', 'ansible-lint', 'flake8']
    })

    result_packages = {line.split()[0] for line in result}
    assert 'yamllint' in result_packages
    assert 'ansible-lint' in result_packages
    assert 'flake8' in result_packages


def test_collection_specified_excluded_requirements_filtered():
    """Test that collection-specified requirements in EXCLUDE_REQUIREMENTS are filtered."""
    # Test that collection-specified yamllint and ansible-lint are filtered out
    result = sanitize_requirements({
        'test.collection': ['yamllint', 'ansible-lint', 'pytest', 'requests']
    })

    result_packages = {line.split()[0] for line in result}
    assert 'yamllint' not in result_packages
    assert 'ansible-lint' not in result_packages
    assert 'pytest' not in result_packages
    assert 'requests' in result_packages


def test_mixed_user_and_collection_requirements():
    """Test mixed user and collection requirements with proper precedence."""
    # User-specified excluded packages should be preserved even if also from collections
    result = sanitize_requirements({
        'user': ['yamllint', 'ansible-lint', 'user-package'],
        'test.collection': ['yamllint', 'pytest', 'collection-package']
    })

    result_packages = [line.split()[0] for line in result]
    result_comments = [line for line in result]

    # yamllint should be preserved (from user) and show both sources
    yamllint_lines = [line for line in result_comments if 'yamllint' in line]
    assert len(yamllint_lines) == 1
    assert 'user' in yamllint_lines[0]
    assert 'test.collection' in yamllint_lines[0]

    # ansible-lint should be preserved (from user only)
    ansible_lint_lines = [line for line in result_comments if 'ansible-lint' in line]
    assert len(ansible_lint_lines) == 1
    assert 'user' in ansible_lint_lines[0]

    # pytest should be filtered out (collection only)
    pytest_lines = [line for line in result_comments if 'pytest' in line]
    assert len(pytest_lines) == 0

    # Other packages should be preserved
    package_names = [pkg for pkg in result_packages]
    assert 'user-package' in package_names
    assert 'collection-package' in package_names

